  1	/* ============================================================
  2	   views/insights.js — Insights view
  3	   Section 4e of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, escapeHtml, formatDate,
  5	               showLoading, showError
  6	   ============================================================ */
  7	
  8	function renderInsights(app) {
  9	  showLoading(app);
 10	
 11	  var allEntries = [];
 12	  var filterType = 'ALL';
 13	  var filterPriority = 'ALL';
 14	  var filterProject = 'ALL';
 15	
 16	  function buildCards() {
 17	    var filtered = allEntries.filter(function (e) {
 18	      if (filterType !== 'ALL' && e.type !== filterType) return false;
 19	      if (filterPriority !== 'ALL' && e.priority !== filterPriority) return false;
 20	      if (filterProject !== 'ALL' && e.project_slug !== filterProject) return false;
 21	      return true;
 22	    });
 23	
 24	    if (!filtered.length) {
 25	      return '<p class="text-muted mt-16">No insights found.</p>';
 26	    }
 27	
 28	    return filtered.map(function (e) {
 29	      var priorityClass = e.priority ? ' priority-' + e.priority : '';
 30	      var contextHtml = '';
 31	      if (e.context && typeof e.context === 'object') {
 32	        var ctxItems = Object.entries(e.context).map(function (pair) {
 33	          return '<span><strong>' + escapeHtml(pair[0]) + ':</strong> ' + escapeHtml(String(pair[1])) + '</span>';
 34	        }).join('<br>');
 35	        contextHtml =
 36	          '<div class="comment-context">' +
 37	            ctxItems +
 38	          '</div>';
 39	      }
 40	      var projectLink = e.repository_name
 41	        ? '<a href="#/projects/' + encodeURIComponent(e.repository_name) + '/' + encodeURIComponent(e.project_slug) + '">' + escapeHtml(e.project_slug) + '</a>'
 42	        : escapeHtml(e.project_slug);
 43	      return '<div class="comment-card' + priorityClass + '">' +
 44	        '<div class="comment-meta">' +
 45	          projectLink +
 46	          ' &mdash; ' +
 47	          escapeHtml(e.agent || '\u2014') +
 48	          ' <span class="comment-type">' + escapeHtml(e.type || '') + '</span>' +
 49	          ' <span>' + escapeHtml(formatDate(e.timestamp)) + '</span>' +
 50	        '</div>' +
 51	        '<div class="comment-body">' + escapeHtml(e.note || '') + '</div>' +
 52	        contextHtml +
 53	      '</div>';
 54	    }).join('');
 55	  }
 56	
 57	  function renderCards() {
 58	    var container = document.getElementById('insights-list');
 59	    if (container) {
 60	      container.innerHTML = buildCards();
 61	    }
 62	  }
 63	
 64	  function render(entries) {
 65	    allEntries = entries;
 66	
 67	    // Collect distinct types and project slugs
 68	    var types = [];
 69	    var projects = [];
 70	    entries.forEach(function (e) {
 71	      if (e.type && types.indexOf(e.type) === -1) types.push(e.type);
 72	      if (e.project_slug && projects.indexOf(e.project_slug) === -1) projects.push(e.project_slug);
 73	    });
 74	    types.sort();
 75	    projects.sort();
 76	
 77	    var typeOptions = types.map(function (t) {
 78	      return '<option value="' + escapeHtml(t) + '">' + escapeHtml(t) + '</option>';
 79	    }).join('');
 80	    var projectOptions = projects.map(function (p) {
 81	      return '<option value="' + escapeHtml(p) + '">' + escapeHtml(p) + '</option>';
 82	    }).join('');
 83	
 84	    app.innerHTML =
 85	      '<div class="page-header"><h1>Insights</h1></div>' +
 86	      '<div class="insights-filters">' +
 87	        '<label for="insights-type">Type:</label>' +
 88	        '<select id="insights-type"><option value="ALL">All types</option>' + typeOptions + '</select>' +
 89	        '<label for="insights-priority">Priority:</label>' +
 90	        '<select id="insights-priority"><option value="ALL">All priorities</option>' +
 91	          '<option value="high">high</option>' +
 92	          '<option value="medium">medium</option>' +
 93	          '<option value="low">low</option>' +
 94	        '</select>' +
 95	        '<label for="insights-project">Project:</label>' +
 96	        '<select id="insights-project"><option value="ALL">All projects</option>' + projectOptions + '</select>' +
 97	      '</div>' +
 98	      '<div id="insights-list">' + buildCards() + '</div>';
 99	
100	    // Restore saved filter values and wire change listeners

  1	/* ============================================================
  2	   views/knowledge.js — Knowledge view
  3	   Section 4f of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, formatDate, showLoading, showError
  5	   ============================================================ */
  6	
  7	function renderKnowledge(app) {
  8	  showLoading(app);
  9	
 10	  /* ── Confidence bucket thresholds ────────────────────────── */
 11	  var CONFIDENCE_HIGH_MIN   = 68;   /* 68–100 → High  */
 12	  var CONFIDENCE_MEDIUM_MIN = 34;   /* 34–67  → Medium */
 13	  /* 0–33 → Low */
 14	
 15	  /* ── View state ──────────────────────────────────────────── */
 16	  var allInsights        = [];
 17	  var activeTab          = 'global';   /* 'global' | 'repository' */
 18	  var filterCategory     = '';
 19	  var filterRepository   = '';
 20	  var filterQuery        = '';
 21	  var editingId       = null;       /* numeric id of card in edit mode */
 22	  var confirmDeleteId = null;       /* numeric id of card in delete-confirm mode */
 23	  var movingId        = null;       /* numeric id of card in move mode */
 24	
 25	  /* ── formatConfidence ────────────────────────────────────── */
 26	  function formatConfidence(value) {
 27	    var pct = Math.round(value * 100);
 28	    var label;
 29	    if (pct >= CONFIDENCE_HIGH_MIN) {
 30	      label = 'High';
 31	    } else if (pct >= CONFIDENCE_MEDIUM_MIN) {
 32	      label = 'Medium';
 33	    } else {
 34	      label = 'Low';
 35	    }
 36	    return pct + '% (' + label + ')';
 37	  }
 38	
 39	  /* ── applyFilters ────────────────────────────────────────── */
 40	  function applyFilters() {
 41	    var scopeValue = activeTab === 'global' ? 'global' : 'repository';
 42	    return allInsights.filter(function (ins) {
 43	      if (ins.scope !== scopeValue) return false;
 44	      if (filterCategory && ins.category !== filterCategory) return false;
 45	      if (activeTab === 'repository' && filterRepository && ins.repository_name !== filterRepository) return false;
 46	      if (filterQuery) {
 47	        var q = filterQuery.toLowerCase();
 48	        var titleMatch    = ins.title   && ins.title.toLowerCase().indexOf(q) !== -1;
 49	        var contentMatch  = ins.content && ins.content.toLowerCase().indexOf(q) !== -1;
 50	        var tagsMatch     = ins.tags    && ins.tags.some(function (t) { return t.toLowerCase().indexOf(q) !== -1; });
 51	        if (!titleMatch && !contentMatch && !tagsMatch) return false;
 52	      }
 53	      return true;
 54	    });
 55	  }
 56	
 57	  /* ── getDistinctValues ───────────────────────────────────── */
 58	  /* Returns { categories: string[], repositories: string[] } — both arrays are
 59	     sorted alphabetically and contain only distinct non-empty values from
 60	     the provided insights array. */
 61	  function getDistinctValues(insights) {
 62	    var categories   = [];
 63	    var repositories = [];
 64	    insights.forEach(function (ins) {
 65	      if (ins.category        && categories.indexOf(ins.category)               === -1) categories.push(ins.category);
 66	      if (ins.repository_name && repositories.indexOf(ins.repository_name)      === -1) repositories.push(ins.repository_name);
 67	    });
 68	    categories.sort();
 69	    repositories.sort();
 70	    return { categories: categories, repositories: repositories };
 71	  }
 72	
 73	  /* ── buildFilterBarHtml ──────────────────────────────────── */
 74	  function buildFilterBarHtml(categories, repositories) {
 75	    var catOptions = categories.map(function (c) {
 76	      return '<option value="' + escapeHtml(c) + '"' + (filterCategory === c ? ' selected' : '') + '>' + escapeHtml(c) + '</option>';
 77	    }).join('');
 78	
 79	    var baseBar =
 80	      '<label for="kn-category">Category:</label>' +
 81	      '<select id="kn-category" class="form-control form-control-sm">' +
 82	        '<option value="">All categories</option>' + catOptions +
 83	      '</select>' +
 84	      '<label for="kn-query">Search:</label>' +
 85	      '<input id="kn-query" type="text" class="form-control form-control-sm" placeholder="Title, content or tag…" value="' + escapeHtml(filterQuery) + '">';
 86	
 87	    if (activeTab === 'repository') {
 88	      var repoOptions = repositories.map(function (r) {
 89	        return '<option value="' + escapeHtml(r) + '"' + (filterRepository === r ? ' selected' : '') + '>' + escapeHtml(r) + '</option>';
 90	      }).join('');
 91	      return (
 92	        '<label for="kn-repository">Repository:</label>' +
 93	        '<select id="kn-repository" class="form-control form-control-sm">' +
 94	          '<option value="">All repositories</option>' + repoOptions +
 95	        '</select>' +
 96	        baseBar
 97	      );
 98	    }
 99	
100	    return baseBar;

  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Unit tests for namespaced project link generation in insights.js and
  5	 * knowledge.js (WP-012).
  6	 *
  7	 * Acceptance criteria tested:
  8	 *   AC-1: `insights.js` project links use `#/projects/{repo}/{slug}` when
  9	 *         `repository_name` is available.
 10	 *   AC-2: `knowledge.js` origin-plan links use `#/projects/{repo}/{slug}`
 11	 *         when `repository_name` is available.
 12	 *   AC-3: Entries with null `repository_name` do not generate broken links —
 13	 *         graceful fallback is applied (plain text, no anchor).
 14	 *   AC-4: No link in either view still uses the bare-slug form without repo.
 15	 *
 16	 * Uses jsdom + vm.runInThisContext to execute the browser-side scripts in
 17	 * the globalThis context, mirroring the approach in client-rendering.test.ts
 18	 * and orchestrator-view.test.ts.
 19	 */
 20	
 21	import { describe, it, expect, beforeAll, vi } from 'vitest';
 22	import { readFileSync } from 'node:fs';
 23	import { join } from 'node:path';
 24	import vm from 'node:vm';
 25	
 26	// ---------------------------------------------------------------------------
 27	// Load scripts
 28	// ---------------------------------------------------------------------------
 29	
 30	const publicDir = join(__dirname, '../../gui/public');
 31	
